{% set customer_doc = frappe.db.get_value("Customer", doc.customer, ["customer_name", "dealer_license_no", "entity_type"], as_dict=1) if doc.customer else {} %}

{% set _addr_link = frappe.db.get_value("Dynamic Link", {"link_doctype": "Customer", "link_name": doc.customer, "parenttype": "Address"}, "parent") %}
{% set _addr = frappe.db.get_value("Address", _addr_link, ["address_line1", "city", "state", "pincode"], as_dict=1) if _addr_link else {} %}
{% set _contact_link = frappe.db.get_value("Dynamic Link", {"link_doctype": "Customer", "link_name": doc.customer, "parenttype": "Contact"}, "parent") %}
{% set _contact = frappe.db.get_value("Contact", _contact_link, ["first_name", "last_name", "phone", "mobile_no", "email_id"], as_dict=1) if _contact_link else {} %}

{%- set effective_date = doc.effective_date or doc.mifa_date or frappe.utils.today() -%}
{%- set entity_type = doc.entity_type or customer_doc.entity_type or "_______________" -%}

{%- macro format_currency(amount) -%}
{{ frappe.utils.fmt_money(amount, currency="USD") }}
{%- endmacro -%}

{%- macro fmt_date(d) -%}
{%- if d -%}{{ frappe.utils.formatdate(d, "MM/dd/yyyy") }}{%- endif -%}
{%- endmacro -%}

<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">

<style>
  .inv {
    font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif !important;
    font-weight: 500 !important; color: #000 !important;
    font-size: 11px !important; line-height: 1.6 !important; width: 100% !important;
  }
  .inv table { border-collapse: collapse !important; width: 100% !important; }
  .inv td, .inv th { padding: 0 !important; vertical-align: top !important; }
  .inv-div {
    border-top: 1px solid #ddd !important; border-bottom: none !important;
    border-left: none !important; border-right: none !important;
    height: 0 !important; margin: 24px 0 !important; background: none !important;
  }
  .lbl { font-weight: 600 !important; font-size: 13px !important; color: #000 !important; padding-bottom: 6px !important; }
  .val { font-size: 13px !important; font-weight: 500 !important; color: #333b44 !important; line-height: 1.4 !important; }
  .inv-items {
    width: 100% !important; border-collapse: separate !important; border-spacing: 0 !important;
    border-radius: 4px !important; overflow: hidden !important;
  }
  .inv-items thead th {
    background: #000 !important; color: #fff !important; font-weight: 600 !important;
    font-size: 12px !important; padding: 12px 20px !important; text-align: left !important;
    letter-spacing: 0.3px !important; border: none !important;
  }
  .inv-items thead tr th:first-child { border-top-left-radius: 4px !important; }
  .inv-items thead tr th:last-child { border-top-right-radius: 4px !important; }
  @media print { .inv-items thead { display: table-row-group !important; } }
  .inv-items tbody td {
    padding: 12px 20px !important; font-size: 12px !important; font-weight: 500 !important;
    color: #333b44 !important; border-bottom: 1px solid #e0e0e0 !important;
    vertical-align: top !important; background: #f5f5f5 !important;
  }
  .inv-items tbody td.f-lbl { font-weight: 700 !important; color: #000 !important; width: 260px !important; }
  .inv-items tbody td.f-val { font-weight: 500 !important; color: #000 !important; }
  .inv-items tbody tr:last-child td { border-bottom: none !important; }
  .inv-items tbody tr:last-child td:first-child { border-bottom-left-radius: 4px !important; }
  .inv-items tbody tr:last-child td:last-child { border-bottom-right-radius: 4px !important; }

  .legal { font-size: 11px !important; line-height: 1.6 !important; color: #333b44 !important; }
  .legal p { margin: 0 0 8px 0 !important; text-align: justify !important; }
  .legal .sec-num { font-weight: 700 !important; color: #000 !important; }
  .legal .sub { padding-left: 24px !important; }
  .legal .sub2 { padding-left: 48px !important; }
  .legal ol { padding-left: 20px !important; margin: 4px 0 8px 0 !important; }
  .legal ol li { margin-bottom: 4px !important; }

  .sig-line {
    border-bottom: 1px solid #333 !important; min-width: 280px !important;
    display: inline-block !important; margin-left: 8px !important;
  }
  .no-break { page-break-inside: avoid !important; }
  .page-break { page-break-before: always !important; }
  .page-num { text-align: center !important; font-size: 10px !important; color: #999 !important; padding-top: 16px !important; }
</style>

<div class="inv">

  <!-- ═══════════════════════════════════════════════════════════ -->
  <!-- PAGE 1 — HEADER & RECITALS                                -->
  <!-- ═══════════════════════════════════════════════════════════ -->

  <div style="text-align: center !important; padding-bottom: 24px !important;">
    <div style="font-size: 18px !important; font-weight: 700 !important; color: #000 !important;">MASTER INVENTORY FINANCING AGREEMENT</div>
  </div>

  <!-- Parties table -->
  <table class="inv-items">
    <thead>
      <tr><th colspan="2">Agreement Parties</th></tr>
    </thead>
    <tbody>
      <tr>
        <td class="f-lbl">"Dealer"</td>
        <td class="f-val">{{ customer_doc.customer_name or '' }}<br>{{ customer_doc.dealer_license_no or '' }}<br>A {{ entity_type }}</td>
      </tr>
      <tr>
        <td class="f-lbl">"Lender"</td>
        <td class="f-val">Dealer Capital Resources, Inc.<br>a California corporation (CFL 603 I934)</td>
      </tr>
      <tr>
        <td class="f-lbl">"Effective Date"</td>
        <td class="f-val">{{ fmt_date(effective_date) }}</td>
      </tr>
    </tbody>
  </table>

  <div class="legal" style="padding-top: 20px !important;">
    <p>This MASTER INVENTORY FINANCING AGREEMENT (which along with any exhibits, and attachments is referred to as the "Agreement") is entered into to be effective as of the above referenced Effective Date between the above referenced Dealer and the above referenced Lender as follows:</p>

    <p><strong>Recitals</strong></p>

    <p>1.1 Dealer engages in the business of purchasing new manufactured homes (each a "Home") from approved manufacturers (each a "Manufacturer") for the purpose of resale. For the terms of this Agreement, all Manufacturers which Dealer will acquire a Home from which will be financed pursuant to this Agreement shall be approved by Lender.</p>

    <p>1.2 Dealer further engages in the business of installing Home(s) with work performed by contractors (each a "Contractor"). Installing may include, but is not limited to, setting of the Home, installing accessories or any other work intended to improve the Home or site the Home is installed on.</p>

    <p>1.3 Dealer has requested Lender to finance Dealer's purchase and/or installation/improving of such Homes and Lender agrees to finance the purchase and installation/improving of the Homes on the terms and conditions of this Agreement.</p>

    <p>1.4 Without modifying any of the other terms or provisions of this Agreement, this Agreement is intended to set forth the terms and provisions governing:</p>

    <div class="sub">
      <p>(a) Lender extending a line of credit to Dealer and advancing funds for the benefit of Dealer (each advance of funds shall be referred to as an "Advance") therefrom which will be used to pay either (i) directly to a Manufacturer all or part of the purchase price of a Home as stated on the Manufacturer's purchase order or invoice to Dealer ("Purchase Price") or (ii) directly to a Contractor to pay the cost of installation and set-up of the Home on a space as stated on the Contractor's invoice or proposal ("Contract Price"); and</p>

      <p>(b) Dealer's obligation to repay each Advance and to pay Lender for other charges, costs or expenses set forth in this Agreement (each an "Other Charge"), together with interest on such Advances and Other Charges at the rates set forth herein.</p>
    </div>

    <p style="font-weight: 600 !important; font-size: 10px !important; text-transform: uppercase !important;">NOW, THEREFORE, FOR VALUABLE CONSIDERATION, THE RECEIPT AND SUFFICIENCY OF WHICH IS HEREBY ACKNOWLEDGED, THE PARTIES HEREBY AGREED AS FOLLOWS:</p>

    <p><span class="sec-num">1. Definitions.</span> In this Agreement, the following terms shall have the following meanings:</p>

    <div class="sub">
      <p>(a) A "Financed Home" shall mean a Home financed by an Advance;</p>
      <p>(b) The "Advance Date" shall mean the date of an Advance made with respect to a Financed Home or paid to a Contractor (whichever occurs first as may be applicable);</p>
      <p>(c) The "First Advance Date" shall mean the date of the initial Advance made with respect to a Financed Home pursuant to the terms of this Agreement (i.e. the date of the first Advance made from the line of credit);</p>
      <p>(d) "Allocated Debt" shall mean any and all Advances, Other Charges and accrued but unpaid interest thereon with respect to any single Financed Home;</p>
      <p>(e) "Aggregate Debt" shall mean the aggregate of all Allocated Debts on all Financed Homes under this Agreement; and</p>
      <p>(f) "Other Charge Date" shall mean with respect to each Other Charge included within Allocated Debt, the date Dealer is first obligated to pay such Other Charge.</p>
    </div>
  </div>

  <div class="page-num">-1-</div>

  <!-- ═══════════════════════════════════════════════════════════ -->
  <!-- PAGE 2 — CREDIT LIMIT & ADVANCES                          -->
  <!-- ═══════════════════════════════════════════════════════════ -->
  <div class="page-break"></div>

  <div class="legal">
    <p><span class="sec-num">2. Line of Credit.</span> Lender hereby grants to Dealer a line of credit, with an approved credit limit of <strong style="color: #c00 !important;">{{ format_currency(doc.credit_limit) if doc.credit_limit else "$(TBD)" }}</strong>, which the parties agree is reasonably expected to be advanced to Dealer and outstanding at some point, for the purpose of Dealer borrowing funds from Lender to acquire one or more Homes and install each Home on a space, including paying the Manufacturer and/or Contractor for work related thereto. From time to time, Lender shall have the right to limit or reduce the line of credit, deny requests for future advances or limit the total number of advances to be made at any one time.</p>

    <p style="padding-top: 4px !important;">Initialed________</p>

    <p><span class="sec-num">3. Advances</span></p>

    <p>3.1 From time to time Lender, in its sole and absolute discretion, at the request of Dealer may make an Advance on behalf of Dealer to a Manufacturer and/or Contractor for the purpose of enabling Dealer to purchase and/or install one Home per Advance.</p>

    <div class="sub">
      <p>3.1.1 Lender, with or without cause and in Lender's sole discretion, may refuse to make any Advance requested by Dealer for any reason or for no reason whatsoever.</p>

      <p>3.1.2 If Dealer requests an Advance to be paid to a Contractor for a Contract Price, the Lender has the right to approve such Contractor, in Lender's sole and absolute discretion. An approval by Lender of a Contractor for a prior Advance (unrelated to the Financed Home in which Dealer desires an Advance for a Contract Price) shall not be deemed an approval by Lender in connection with the current Financed Home or Advance sought by Dealer.</p>

      <p>3.1.3 No Advance for the purchase of a Home shall exceed 100 percent of the Purchase Price stated on the Manufacturer's purchase order or invoice to Dealer (the "Purchase Order") for the Financed Home. Under no circumstances shall the Purchase Price include any additional charges except charges for delivery of the Financed Home to Dealer (if such charges are included on the Purchase Order).</p>

      <p>3.1.4 No Advance for the improvement and placement of a Home shall exceed 100 percent of the Contract Price for the Financed Home. Lender shall make each Advance directly to the Contractor with respect to any the improvements specifically associated with a Financed Home and each such Advance, when made, shall be deemed to have been made to and for the benefit of Dealer.</p>

      <p>3.1.5 Unless Lender designates another form of document, Dealer shall execute in favor of Lender a receipt (a "Receipt") in substantially the form and substance of Exhibit A attached hereto for the Advance extended with respect to each Financed Home.</p>

      <p>3.1.6 Dealer shall deliver or cause to be delivered to Lender the Manufacturer's Certificate of Origin (an "MCO") for each Financed Home at the time such Financed Home is shipped by the Manufacturer. Lender shall retain each such MCO until all Allocated Debt for the Financed Home is paid in full by Dealer to Lender.</p>
    </div>

    <p>3.2 Notwithstanding any provision of this Agreement to the contrary, the Aggregate Debt shall not exceed such amount as Lender shall establish from time to time by notice from Lender to Dealer. With respect to each Financed Home, Lender shall keep a record of each Advance, the Advance Date thereof and the amount of the Allocated Debt, which record shall be conclusive evidence thereof absent manifest error.</p>

    <p>3.3 From time to time Lender may send Dealer a statement of the transactions (a "Statement") identifying each Financed Home, each Advance made with respect thereto and its Advance Date and the amount of Allocated Debt related thereto. Dealer shall sign the Statement and return a copy to Lender; however, regardless of such signing by Dealer, Dealer shall be deemed to have accepted and acknowledged the accuracy thereof unless Dealer notifies Lender of any correction or objection thereto within five days after the date of delivery of the Statement to Dealer.</p>
  </div>

  <div class="page-num">-2-</div>

  <!-- ═══════════════════════════════════════════════════════════ -->
  <!-- PAGE 3 — REPAYMENT TERMS (Section 4)                      -->
  <!-- ═══════════════════════════════════════════════════════════ -->
  <div class="page-break"></div>

  <div class="legal">
    <p><span class="sec-num">4. Repayment Terms.</span> Dealer shall pay to the order of Lender, at such place as Lender may designate from time to time, the Aggregate Debt, interest due thereon and such other charges and expenses as follows:</p>

    <p>4.1 <em>Accrual of Interest.</em> Interest shall accrue on each unpaid Advance and on each Other Charge at the interest rates set forth below, compounded annually as follows:</p>

    <div class="sub">
      <p>4.1.1 So long as there exists no uncured Event of Default (as defined below), interest hereunder shall accrue on each unpaid Advance or Other Charge at the rate of 12 percent per annum from the respective Advance Date or Other Charge Date until the Aggregate Debt is paid in full.</p>

      <p>4.1.2 Notwithstanding the foregoing, so long as there exists an uncured Event of Default, interest hereunder shall accrue on each unpaid Advance or Other Charge at the rate of 18 percent per annum from the respective Advance Date or Other Charge Date until the loan is paid in full.</p>

      <p>4.1.3 In no event shall the amount paid, or agreed to be paid, to Lender as interest or for the use, forbearance or detention of money to be loaned hereunder or otherwise, or for the payment or performance of any covenant or obligation contained herein, exceed the maximum amount permissible under applicable law.</p>
    </div>

    <p>4.2 <em>Payment.</em> For the first through twelfth months after the Advance Date, Dealer shall pay to Lender an interest only payment equal to the interest rate described in paragraph 4.1.1 above times the Advance divided by 12 (interest only payment), which payments shall be made monthly commencing on the first day of the month after the Advance Date. For the thirteen through twenty-fourth months after the Advance Date, Dealer shall pay to Lender an interest plus principal payment in the amount of the interest rate described in paragraph 4.1.1. above, times the Advance, divided by 12, plus a payment towards reduction of the outstanding principal of One percent (1%) of the outstanding Aggregate Debt for a Financed Home. Each payment due under this paragraph shall be hereinafter referred to as a "Monthly Payment" and each Monthly Payment shall be due on the first of each month.</p>

    <p>4.3 <em>Maturity Date.</em> Dealer shall pay to Lender the entire Allocated Debt with respect to any Financed Home, whether paid to a Manufacturer or a Contractor, on or before the earlier to occur of (the "Maturity Date"):</p>

    <div class="sub">
      <p>(a) The date that is the twenty-fourth (24th) month after the Advance Date;</p>
      <p>(b) The date of Dealer's resale of such Financed Home;</p>
      <p>(c) The date of any occupancy by any person of the Financed Home regardless of a transfer of title to the Financed Home; or</p>
      <p>(d) The date any Event of Default occurs under this Agreement.</p>
    </div>

    <p>4.4 <em>Late Fee.</em> A late fee of 10 percent of the Monthly Payment plus any Other Charges due shall be due in addition to the Monthly Payment if any Monthly Payment arrives at Lender's office more than 15 days after the Monthly Payment due date.</p>

    <p>4.5 <em>Other Charges.</em></p>

    <div class="sub">
      <p>4.5.1 As an Other Charge under this Agreement, Dealer shall pay monthly following a First Advance Date an insurance charge for the premium cost of any casualty insurance maintained by Lender (and as to which Lender or its assignee is the beneficiary or payee) on the related Financed Home. Lender in its sole and absolute discretion may obtain such insurance covering only such Financed Home or blanket insurance covering all or any number Homes for which Lender has loaned money, whether or not such Home is a Financed Home under this Agreement or a Home financed by Lender for other persons. In the case of blanket insurance, Lender's allocation of the premium cost to a Home financed by an Advance under this Agreement shall be binding and conclusive in the absence of manifest error, fraud or undue influence.</p>

      <p>4.5.2 As an Other Charge under this Agreement, Lender may charge Dealer an Acquisition Fee of 1% of the Advance amount.</p>
    </div>

    <p>4.6 <em>Method of Payments.</em> All amounts payable by Dealer under this Agreement shall be paid in cash to Lender's account as Lender may instruct Dealer, and if Lender so elects, by authorized automatic funds transfer with Dealer's banking institution.</p>

    <p>4.7 <em>Future Advances.</em> Lender has the right to modify the payment terms herein upon prior notice to Dealer and Dealer shall have the option to terminate this Agreement with notice and provided that all outstanding Aggregate Debt due hereunder is paid in full.</p>
  </div>

  <div class="page-num">-3-</div>

  <!-- ═══════════════════════════════════════════════════════════ -->
  <!-- PAGES 4-8 — SECURITY INTEREST, DEFAULT, REMEDIES           -->
  <!-- (Sections 5-7 — entirely static legal boilerplate)          -->
  <!-- ═══════════════════════════════════════════════════════════ -->
  <div class="page-break"></div>

  <div class="legal">
    <p><span class="sec-num">5. Grant of Security Interest and Dealer Obligations</span></p>

    <p>5.1 To secure the prompt and complete payment of the Aggregate Debt and performance of all of Dealer's obligations to Lender under this Agreement and under all Receipts and other documents executed and delivered from time to time in connection herewith, whether now in existence or hereafter arising, Dealer grants to Lender a security interest in all of Dealer's right, title and interest in and to the following property, whether now owned or existing or hereafter acquired or arising (collectively, the "Collateral"):</p>

    <div class="sub">
      <p>(a) any and all Financed Homes (including Homes described in the Receipts or the Purchase Orders), along with: (1) all improvements or items attached to the Financed Homes by Dealer or others; (2) all additions, replacements or substitutions relating to any of the foregoing whether owned now or later acquired for the benefit of any Financed Home; and (3) all records of any kind relating to any of the foregoing;</p>
      <p>(b) all goods and inventory of Dealer, in addition to the Financed Homes, but which are related to the ownership, operation, maintenance or financing of any Financed Home;</p>
      <p>(c) all accounts, chattel paper, instruments, contract rights, policies and certificates of insurance, documents, investment property, commercial tort claims, money, books and records and general intangibles, including all monies and credits now due or to become due to Dealer from, and all claims against, Manufacturers arising out of or relating to any of the foregoing;</p>
      <p>(d) all titles, permits, licenses, approvals, grants or rights issued by any governmental authority or park relating to the movement, placement, installation and potential occupancy of the Financed Home and ancillary improvements; and</p>
      <p>(e) all proceeds of the foregoing including insurance proceeds, general intangibles and account proceeds.</p>
    </div>

    <p>5.2 Dealer shall execute such documents and take such actions, and provide such information, as Lender shall reasonably request, to confirm, perfect or maintain Lender's security interest in the Collateral.</p>

    <p>5.3 Dealer shall execute all security agreements, financing statements, loan applications, authorizations, loan statements, subordination agreements, estoppels, park owner and landlord consents and other agreements and documents, and shall post notices or signs with respect to the Collateral and take such other action, as Lender may reasonably request from time to time.</p>

    <p>5.4 Dealer hereby grants to Lender a power of attorney to: (a) execute financing statements and other documents on Dealer's behalf, (b) file any and all financing statements, including any continuations, transfers or amendments thereof, without authentication or execution by Dealer; and (c) give notice of this Agreement and the rights of Lender under this Agreement to any creditors of Dealer. Dealer acknowledges that the foregoing power of attorney grant is coupled with an interest and is irrevocable for so long as Dealer has any obligations to Lender under this Agreement.</p>

    <p>5.5 Dealer shall hold each Financed Home and proceeds thereof in trust until all Allocated Debt thereon has been paid and satisfied in full and Lender has notified Dealer of the termination of Lender's security interest in the Financed Home.</p>

    <p>5.6 Lender's title, lien or security interest shall not be impaired by any payment to the Manufacturer or anyone else, in whole or in part, of the Purchase Price or any payment to the Contractor, in whole or in part, of the Contract Price.</p>

    <p>5.7 Lender's security interest in each Financed Home shall be deemed a purchase money security interest under and as defined in the California Uniform Commercial Code to the extent of the Advance made to enable Dealer to acquire such Financed Home.</p>

    <p>5.8 As an ongoing obligation of Dealer and for the benefit of protecting and securing the Collateral, Dealer shall:</p>

    <div class="sub">
      <p>(a) keep the Collateral only at locations previously approved by Lender;</p>
      <p>(b) except as otherwise provided in this Agreement, not sell, transfer, encumber, license, lease, rent, let out, mortgage or otherwise dispose of any Financed Home or other Collateral without the prior consent of Lender;</p>
      <p>(c) prior to the installation and/or placement of the Financed Home, obtain all consents, authorizations and approvals required from the owner or manager of the mobile/manufactured home park;</p>
      <p>(d) prior to the installation and/or placement of the Financed Home, obtain all required permits, licenses, consents or authorizations from applicable governmental agencies;</p>
      <p>(e) within 60 days after each Financed Home is shipped by the Manufacturer: (1) install or cause to be installed such Financed Home on the applicable premises; (2) complete and lay the drywall and the carpeting; and (3) obtain the Certificate of Occupancy and deliver a copy to Lender;</p>
      <p>(f) comply with all applicable laws, ordinances, regulations and orders;</p>
      <p>(g) keep and maintain the Collateral in good repair and insured;</p>
      <p>(h) permit Lender to inspect any or all Collateral at all reasonable times;</p>
      <p>(i) maintain its organizational existence in good standing;</p>
      <p>(j) promptly file all tax returns and pay all taxes;</p>
      <p>(k) obtain and maintain all licenses, franchises, permits and approvals required;</p>
      <p>(l) keep complete and accurate records of its business;</p>
      <p>(m) conduct its business in a manner consistent with its current business;</p>
      <p>(n) furnish Lender with such additional information as Lender may request;</p>
      <p>(o) not engage in any business requiring Lender to become licensed by any authority;</p>
      <p>(p) not assert against Lender any claim or defense Dealer may have against any Manufacturer or Contractor; and</p>
      <p>(q) notify the management of the mobile home park that the Lender is a Secured Inventory Creditor.</p>
    </div>

    <p>5.9 Dealer absolutely and unconditionally represents and warrants to Lender as of the Effective Date and each Advance Date or Other Charge Date that:</p>

    <div class="sub">
      <p>(a) Dealer has all requisite power, authority and licenses to conduct its business;</p>
      <p>(b) Dealer has full right and power to grant the security interest granted herein;</p>
      <p>(c) Dealer is not in default with respect to any agreement to which it is a party;</p>
      <p>(d) Dealer is not in violation of any applicable statute or regulation;</p>
      <p>(e) Dealer is engaged in the business of buying and reselling Homes to customers at retail;</p>
      <p>(f) Dealer is a duly authorized and licensed "dealer" of such Homes;</p>
      <p>(g) Dealer is the owner of the Collateral, free and clear of any liens;</p>
      <p>(h) the Collateral is and shall remain free and clear of all liens except for the security interest granted herein;</p>
      <p>(i) no financing statement covering the Collateral, other than one relating hereto, is on file;</p>
      <p>(j) the obligations of Dealer arise out of or in connection with business purposes; and</p>
      <p>(k) Dealer is not relying on any legal advice from Lender.</p>
    </div>

    <p>5.10 Dealer shall pay all taxes and assessments levied on the Collateral and shall keep the Collateral insured against such risks and in such amounts as Lender may require.</p>

    <p>5.11 Unless and until an Event of Default shall have occurred, Dealer may sell Financed Homes to buyers in the ordinary course of Dealer's business.</p>

    <div class="sub">
      <p>5.11.1 No Financed Home shall be sold for less than the Purchase Price without Lender's prior consent.</p>
      <p>5.11.2 Simultaneously with any sale of a Financed Home, Dealer shall pay over to Lender an amount equal to the Allocated Debt with respect to such Financed Home.</p>
    </div>

    <p><span class="sec-num">6. Events of Default and Remedies</span></p>

    <p>6.1 Each of the following shall constitute an "Event of Default" under this Agreement:</p>

    <div class="sub">
      <p>(a) Dealer's failure to pay when due any amount payable;</p>
      <p>(b) Dealer's failure to perform any other obligation or covenant;</p>
      <p>(c) a breach or default by Dealer under any other agreement with Lender;</p>
      <p>(d) any warranty or representation becomes false in any material respect;</p>
      <p>(e) the loss, theft, damage, destruction, sale or encumbrance of any of the Collateral;</p>
      <p>(f) the inability of Dealer to pay debts as they mature, insolvency, or bankruptcy proceedings;</p>
      <p>(g) the dissolution, merger or consolidation of Dealer; and</p>
      <p>(h) failure to pay Space Rent to any mobile home park.</p>
    </div>

    <p>6.2 Lender may cure any Event of Default without waiving the default cured and may waive any Event of Default without waiving any other prior or subsequent Event of Default.</p>

    <p>6.3 Whenever an Event of Default shall occur, Lender may declare the Aggregate Debt immediately due and payable.</p>

    <p>6.4 Lender shall have the remedies of a secured party under the California Uniform Commercial Code with respect to the Collateral.</p>

    <div class="sub">
      <p>6.4.1 Dealer shall be liable for reasonable expenses incurred by Lender in enforcing its rights and remedies.</p>
      <p>6.4.2 Proceeds from disposition of Collateral shall be applied toward Aggregate Debt in such order as Lender may elect. Dealer shall remain liable for any deficiency.</p>
      <p>6.4.3 The rights and remedies of Lender are cumulative.</p>
    </div>

    <p>6.5 Dealer shall pay all fees and costs incurred by Lender in enforcing Lender's rights, including reasonable attorneys' fees.</p>

    <p>6.6 In the event of the death, permanent disability or incapacity of the principal person of Dealer, the full outstanding Aggregate Debt shall be fully due and payable within fifteen (15) days.</p>

    <p>6.7 Lender may terminate Lender's obligations under this Agreement at any time without cause upon notice to Dealer.</p>

    <p><span class="sec-num">7. Indemnity</span></p>

